AnnotationValues<Accessors> lookupAccessorsForField(JavacNode field) {
	this.fieldScanType = field;
	AnnotationValues<Accessors> values = findAccessorsOnNode(field);
	JavacNode current = field.up();
	while (current != null) {
		AnnotationValues<Accessors> onType = findAccessorsOnNode(current);
		if (onType != null) values = values == null ? onType : values.integrate(onType);
		current = current.up();
	}
	return values == null ? AnnotationValues.of(Accessors.class, field) : values;
}

AnnotationValues<Accessors> findAccessorsOnNode(JavacNode owner) {
	this.fieldScanType = owner;
	if (owner == null) return null;
	for (JavacNode node : owner.down()) {
		if (annotationTypeMatchesClass(Accessors.class, node)) {
			return JavacHandlerUtil.createAnnotation(Accessors.class, node);
		}
	}
	return null;
}


